package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
import net.minecraft.world.level.block.Blocks;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsTrade {
 @GameTest(template="empty") public static void hungryFamilyPurchasesIncludeRecovery(GameTestHelper h){var d=new RuralSettlement();var p=CityTestsRural.person();p.nourishment=10;var f=CityTestsRural.family(p);d.state.people.put(p.id,p);d.state.families.put(f.id,f);for(int i=0;i<3;i++){var box=new RuralSettlement.Box();box.linked=true;box.stock.family=f.id;d.state.boxes.put("b"+i,box);}h.assertTrue(CityTrade.mealTarget(f,d)>p.meal()*2,"Recovery needs more than merely matching the next deduction");h.succeed();}
 @GameTest(template="empty") public static void headMeatPurchasesCannotSpendGrainWorkingReserve(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var link=f.box();var box=NpcStorage.box(link);box.linked=true;box.stock.family=f.person.family;f.person.role=RuralRules.Role.MERCHANT;var farmer=CityTestsRural.person();farmer.family=f.person.family;farmer.role=RuralRules.Role.FARMER;d.state.people.put(farmer.id,farmer);d.state.families.get(f.person.family).members.add(farmer.id);f.city.residents.add(farmer.id);var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;t.state.towns.put(f.city.id,town);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.worker=f.worker;b.kind="head";t.state.businesses.put(b.id,b);long reserve=CityTrade.headReserve(f.server,f.city.id);UUID seller=UUID.randomUUID();var source=new RuralRules.Stock();source.raw[0]=1;source.wheat=1;var money=new HashMap<UUID,Long>();money.put(f.worker,reserve);money.put(seller,0L);var family=d.state.families.get(f.person.family);int meat=RuralMarket.buy(d,f.person,family,seller,List.of(source),d.stocks(family.id),2,1,8,money);int wheat=RuralMarket.buy(d,f.person,family,seller,List.of(source),d.stocks(family.id),0,1,2,money);h.assertTrue(reserve>0&&meat==0&&wheat==1&&money.values().stream().mapToLong(Long::longValue).sum()==reserve,"Reserved money remains spendable on staple inputs but not meat");t.state.businesses.remove(b.id);t.state.towns.remove(f.city.id);}h.succeed();}
 @GameTest(template="empty") public static void personalFoodCanUseOwnBusinessWithoutMinting(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var link=f.box();var box=NpcStorage.box(link);box.linked=true;box.stock.family=f.person.family;var e=CityEconomy.get(f.server);var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;t.state.towns.put(f.city.id,town);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.worker=f.worker;b.kind="procurement";b.account="trade:test:"+b.id;t.state.businesses.put(b.id,b);e.state.accounts.put(b.account,100L);e.state.accounts.put(CityEconomy.person(f.worker),0L);long total=f.money();t.supportOwnerMeal(f.server,RuralSettlement.get(f.server).state.families.get(f.person.family));h.assertTrue(e.balance(CityEconomy.person(f.worker))>0&&e.balance(b.account)<100&&f.money()==total,"Next family meal outranks frozen operating capital through a real owner transfer");t.state.businesses.remove(b.id);t.state.towns.remove(f.city.id);e.state.accounts.remove(b.account);}h.succeed();}
 @GameTest(template="empty") public static void oneWorkerProducesHalfAndNoWorkerProducesNothing(GameTestHelper h){var none=TradeRules.supplierOutput(0,0,8,8);var one=TradeRules.supplierOutput(1,0,8,8);var two=TradeRules.supplierOutput(2,0,8,8);h.assertTrue(none[0]+none[1]==0&&one[0]+one[1]==1&&two[0]+two[1]==2,"Available paid workers bound production");var limited=TradeRules.supplierOutput(2,0,0,1);h.assertTrue(limited[0]+limited[1]==1,"Storage cannot create extra supply");h.succeed();}
 @GameTest(template="empty") public static void lossOffsetsFutureTaxableProfit(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.worker=f.worker;b.account=CityEconomy.person(f.worker);var t=CityTrade.get(f.server);t.profit(f.server,b,3,1000);h.assertTrue(b.expenseCents==700,"Realized loss carried, not erased");t.profit(f.server,b,12,500);h.assertTrue(b.expenseCents==0&&b.profitCents==0,"Recovery to break-even does not create taxable gain");}h.succeed();}
 @GameTest(template="empty") public static void configRejectsNonFiniteAndExcessiveWork(GameTestHelper h){var c=new CityTrade.Config();CityTrade.validate(c);c.targets[0]=Double.NaN;boolean rejected=false;try{CityTrade.validate(c);}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected,"Invalid prices cannot enter runtime");c=new CityTrade.Config();c.listingTicks=1;rejected=false;try{CityTrade.validate(c);}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected,"Cannot configure unbounded per-tick listing");h.succeed();}
 @GameTest(template="empty") public static void ruralAndUrbanArtisansUseDistinctSalary(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);d.state.enabled.add(f.city.id);h.assertTrue(CityWorksFinance.wage(f.server,f.city,true)==3&&CityWorksFinance.wage(f.server,f.city,false)==3,"Existing rural mode gets rural wage too");var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;t.state.towns.put(f.city.id,town);h.assertTrue(CityWorksFinance.wage(f.server,f.city,true)==7&&CityWorksFinance.wage(f.server,f.city,false)==7,"Urban household mode retains city wage");t.state.towns.remove(f.city.id);}h.succeed();}
 @GameTest(template="empty") public static void threeDayBrokenJobResignsToResidentWithoutMoney(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var site=d.state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();site.expectedBlock="minecraft:crafting_table";CityWorks.schedule(f.city,site.pos,Blocks.AIR.defaultBlockState(),Blocks.CRAFTING_TABLE.defaultBlockState(),"TEST");long cash=f.money();RuralTools.resignBlocked(f.server,f.city,0);RuralTools.resignBlocked(f.server,f.city,71999);h.assertTrue(site.worker.equals(f.worker),"No immediate dismissal");RuralTools.resignBlocked(f.server,f.city,72000);h.assertTrue(site.worker==null&&f.person.role==RuralRules.Role.NONE&&f.city.residents.contains(f.worker)&&f.money()==cash,"Voluntary departure preserves citizenship and finances");}h.succeed();}
 @GameTest(template="empty") public static void legacyEmptyExpectedTypeCannotAdoptWrongStation(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var site=RuralSettlement.get(f.server).state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();site.expectedBlock="";site.kind="farmer";h.getLevel().setBlock(f.bench,RuralBlocks.STOVE.get().defaultBlockState(),3);h.assertTrue(!RuralTools.available(f.server,site)&&site.worker.equals(f.worker),"Legacy binding cannot turn a stove into a farming point");}h.succeed();}
 @GameTest(template="empty") public static void emptyPremiumHasExactThirtyDayCap(GameTestHelper h){h.assertTrue(TradeRules.factor(0,100,0,0)==2,"Initial shortage doubles standard");h.assertTrue(Math.abs(TradeRules.factor(0,100,24000*30L,0)-5)<1e-8,"Thirty days reaches 500%, not compounded");h.assertTrue(TradeRules.factor(0,100,24000*300L,0)==5,"Cap is persistent");h.succeed();}
 @GameTest(template="empty") public static void richDiscountStopsAtFourDays(GameTestHelper h){h.assertTrue(TradeRules.factor(200,100,0,0)==.5,"Twice target starts at half price");h.assertTrue(Math.abs(TradeRules.factor(200,100,0,24000*4L)-.1)<1e-8,"Four days reaches ten percent");h.assertTrue(TradeRules.quote(3,200,100,0,24000*40L)==1,"Integer price never zero");h.succeed();}
 @GameTest(template="empty") public static void priceRecoveryClearsContinuousClock(GameTestHelper h){var p=new TradeRules.Price();TradeRules.observe(p,0,10,100);TradeRules.observe(p,0,10,24100);h.assertTrue(p.emptySince==100,"Continuous empty duration preserved");TradeRules.observe(p,1,10,24101);h.assertTrue(p.emptySince==-1,"Actual restock ends empty streak");TradeRules.observe(p,20,10,25000);TradeRules.observe(p,19,10,26000);h.assertTrue(p.richSince==-1,"Stock falls below twice target clears rich streak");h.succeed();}
 @GameTest(template="empty") public static void costAndOwnershipSurvivePartialMoves(GameTestHelper h){var a=new TradeRules.Lot();var b=new TradeRules.Lot();a.add(3,1000);a.add(2,901);TradeRules.move(a,b,2);h.assertTrue(a.count+b.count==5&&a.cents+b.cents==1901,"Partial listing preserves every portion and cost cent");TradeRules.move(a,b,3);h.assertTrue(a.cents==0&&a.count==0&&b.cents==1901,"Final transfer carries rounding remainder");h.succeed();}
 @GameTest(template="empty") public static void independentPartiesCanOverbuy(GameTestHelper h){int a=TradeRules.plan(0,100,5,4,1,384,1000),b=TradeRules.plan(0,100,5,4,1,384,1000);h.assertTrue(a==b&&a>0&&a+b>a,"Identical old snapshots independently plan same cargo");h.assertTrue(TradeRules.quote(5,a+b,100,0,0)<TradeRules.quote(5,a,100,0,0),"Both returning can depress price");h.succeed();}
 // A four-coin source exercises distinct integer sale thresholds for the current procurement margin.
 // A more optimistic observation must still produce a strictly larger plan.
 @GameTest(template="empty") public static void perceptionRangeAndPlanDifference(GameTestHelper h){h.assertTrue(TradeRules.estimate(0)==.9&&TradeRules.estimate(2000)==1.1,"Perception stays within +/-10%");int low=TradeRules.plan(0,100,5,4,.9,384,1000),high=TradeRules.plan(0,100,5,4,1.1,384,1000);h.assertTrue(low<high,"Optimistic estimate purchases more");h.succeed();}
 @GameTest(template="empty") public static void cargoLimitsDoNotBecomeSingleStackTotal(GameTestHelper h){var cargo=TradeRules.lots();cargo[0].add(192,57600);cargo[2].add(1,1500);h.assertTrue(TradeRules.capacity(cargo)==191,"Per-item192 and total384 remain distinct");h.assertTrue(TradeRules.plan(0,100,5,3,1,384,12)<=4,"Actual money bounds plan");h.succeed();}
 @GameTest(template="empty") public static void consignmentDoesNotGenerateCash(GameTestHelper h){var source=new TradeRules.Lot();var listed=new TradeRules.Lot();source.add(12,3600);long cash=1000;TradeRules.move(source,listed,12);h.assertTrue(cash==1000&&listed.count==12,"Listing changes location, not sale or cash");h.succeed();}
 @GameTest(template="empty") public static void saveKeepsCargoCostAndPerception(GameTestHelper h){var st=new CityTrade.State();var b=new CityTrade.Business();b.id=UUID.randomUUID();b.worker=UUID.randomUUID();b.city=UUID.randomUUID();b.phase=1;b.perception=.937;b.cargo[0].add(71,21300);st.businesses.put(b.id,b);var loaded=CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(st),CityTrade.State.class);var c=loaded.businesses.get(b.id);h.assertTrue(c.phase==1&&c.perception==.937&&c.cargo[0].count==71&&c.cargo[0].cents==21300,"Reload does not reroll or duplicate cargo");h.succeed();}
 @GameTest(template="empty") public static void dataRepairRestoresJobWithoutRebinding(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var site=d.state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();site.expectedBlock="minecraft:crafting_table";f.house.damaged.add(site.pos);CityWorks.schedule(f.city,site.pos,Blocks.AIR.defaultBlockState(),Blocks.CRAFTING_TABLE.defaultBlockState(),"TEST");h.assertTrue(!RuralTools.available(f.server,site)&&f.worker.equals(site.worker),"Destroyed site pauses and retains worker");CityWorks.schedule(f.city,site.pos,Blocks.CRAFTING_TABLE.defaultBlockState(),Blocks.AIR.defaultBlockState(),"REPAIR");f.house.damaged.remove(site.pos);h.assertTrue(RuralTools.available(f.server,site)&&f.worker.equals(site.worker),"Authoritative pending repair restores work before projection");}h.succeed();}
 @GameTest(template="empty") public static void wrongBlockCannotRestoreBoundProfession(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var site=RuralSettlement.get(f.server).state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();site.expectedBlock="minecraft:crafting_table";CityWorks.schedule(f.city,site.pos,Blocks.FURNACE.defaultBlockState(),Blocks.CRAFTING_TABLE.defaultBlockState(),"TEST");h.assertTrue(!RuralTools.available(f.server,site)&&site.worker.equals(f.worker),"Different block at same position neither rebinds nor resumes");}h.succeed();}
 @GameTest(template="empty") public static void taxConservesCashAndCarriesFraction(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var t=CityTrade.get(f.server);long before=f.money();long tax=0;for(int i=0;i<20;i++)tax+=t.tax(f.server,CityEconomy.person(f.worker),f.city.id,4,5,"test:"+f.worker);h.assertTrue(tax==4&&f.money()==before,"20x4 at5% taxes four existing coins, no mint");t.state.taxTails.remove("test:"+f.worker);}h.succeed();}
}

